<template>
  <main class="min-h-screen bg-paper px-4 py-8"><div class="mx-auto max-w-2xl"><header class="text-center"><p class="text-xs font-semibold uppercase tracking-[.2em] text-amber">BookPath Evaluation</p><h1 class="mt-3 text-3xl font-semibold text-navy">推荐体验评测</h1><p class="mt-3 text-sm leading-6 text-black/45">使用匿名测试编号，不关联你的账号、学号或其他敏感身份信息。</p></header><form class="mt-7 space-y-6 rounded-3xl bg-white p-6 shadow-card sm:p-8" @submit.prevent="submit"><div class="grid gap-4 sm:grid-cols-2"><label><span class="label">匿名测试编号</span><input v-model="form.tester_code" class="field" pattern="[A-Za-z0-9_-]{4,64}" required /></label><label><span class="label">画像场景</span><select v-model="form.profile_scenario" class="field" required><option v-for="item in scenarios" :key="item">{{ item }}</option></select></label></div><fieldset v-for="metric in metrics" :key="metric.key"><div class="flex items-center justify-between"><legend class="label">{{ metric.label }}</legend><strong class="text-navy">{{ form[metric.key] }} 分</strong></div><div class="mt-2 grid grid-cols-5 gap-2"><label v-for="score in 5" :key="score" class="score" :class="form[metric.key] === score && 'score-active'"><input v-model.number="form[metric.key]" class="sr-only" type="radio" :value="score" />{{ score }}</label></div></fieldset><label class="block"><span class="label">补充意见（可选）</span><textarea v-model="form.notes" class="field min-h-24 py-3" maxlength="1000" /></label><div v-if="message" class="rounded-xl px-4 py-3 text-sm" :class="success ? 'bg-sage/10 text-sage' : 'bg-red-50 text-red-700'">{{ message }}</div><button class="min-h-12 w-full rounded-xl bg-navy font-semibold text-white" :disabled="submitting || success">{{ submitting ? '提交中…' : success ? '评价已提交' : '提交匿名评价' }}</button></form><div class="mt-5 text-center"><RouterLink class="text-sm font-medium text-navy" to="/workspace">返回学习工作台</RouterLink></div></div>
  </main>
</template>
<script setup lang="ts">
import { reactive, ref } from 'vue'; import { useRoute } from 'vue-router'; import { createEvaluation } from '@/api/evaluations'; import { getApiErrorMessage } from '@/utils/apiError'
type ScoreKey = 'relevance_score' | 'difficulty_score' | 'reason_score' | 'holding_score' | 'satisfaction_score'
const route = useRoute(); const storedCode = localStorage.getItem('bookpath_tester_code') || `tester_${crypto.randomUUID().slice(0, 8)}`; localStorage.setItem('bookpath_tester_code', storedCode)
const scenarios = ['大一零基础学习 Java', '大二计算机学生学习数据库', '非计算机专业了解人工智能', '有基础，希望做 Java 项目实践', '偏好理论或案例的对照画像']; const metrics: { key: ScoreKey; label: string }[] = [{ key: 'relevance_score', label: '与学习目标相关性' }, { key: 'difficulty_score', label: '难度与基础匹配' }, { key: 'reason_score', label: '推荐理由可信度' }, { key: 'holding_score', label: '馆藏信息实用性' }, { key: 'satisfaction_score', label: '整体满意度' }]
const form = reactive({ tester_code: storedCode, profile_scenario: scenarios[0], recommendation_set_id: String(route.params.setId), relevance_score: 5, difficulty_score: 5, reason_score: 5, holding_score: 5, satisfaction_score: 5, notes: '' }); const submitting = ref(false); const success = ref(false); const message = ref('')
async function submit() { submitting.value = true; try { await createEvaluation({ ...form, notes: form.notes.trim() || null }); success.value = true; message.value = '感谢参与。该评分仅作为当前样本的人工评测，不代表普遍准确率。' } catch (error) { message.value = getApiErrorMessage(error, '评价提交失败') } finally { submitting.value = false } }
</script>
<style scoped>.label { @apply text-sm font-medium text-navy; }.field { @apply mt-2 min-h-11 w-full rounded-xl border border-black/10 px-3 outline-none focus:border-navy; }.score { @apply grid min-h-11 cursor-pointer place-items-center rounded-xl border border-black/10 text-sm; }.score-active { @apply border-navy bg-navy text-white; }</style>
